INSERT INTO ilb_psoriasis_treatment_class(class_id,class_name,route_or_type,mechanism_summary,typical_role,major_safety_theme,governance_text,source_url) VALUES
('TXC-001','Emollients/barrier care','Topical supportive','Barrier hydration; symptom/scale support','Mild disease/supportive across phenotypes','Not disease-modifying alone in moderate-severe disease','Routine adjunct','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-002','Topical corticosteroids','Topical anti-inflammatory','Broad anti-inflammatory transcriptional effects','Many plaque/site presentations with site-specific potency choices','Skin atrophy and other local/systemic risks depend on potency/site/duration','Guideline-based','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-003','Vitamin D analogues','Topical','Keratinocyte differentiation and immune modulation','Plaque psoriasis','Irritation/hypercalcemia risk if excessive systemic exposure','Guideline-based','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-004','Topical nonsteroid agents','Topical','Examples include PDE4/AhR/retinoid pathways','Site-appropriate mild/moderate disease','Agent-specific safety','Guideline-based','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-005','NB-UVB / targeted UVB','Phototherapy','Immune and epidermal effects of UVB','Widespread plaque/guttate and selected sites','Burn/photoaging; regimen-dependent','Evidence-based','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-006','Methotrexate','Traditional systemic','Folate-pathway/immune effects','Moderate-severe psoriasis/PsA context','Hepatic, marrow, pregnancy and interaction risks','Medical monitoring required','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-007','Cyclosporine','Traditional systemic','Calcineurin inhibition','Rapid control of severe disease in selected patients','Renal/BP/infection/malignancy risks; usually limited duration','Medical monitoring required','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-008','Acitretin','Oral retinoid','Retinoid receptor effects on keratinization','Severe plaque/pustular contexts','Highly teratogenic; lipid/liver/mucocutaneous risks','Medical monitoring required','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-009','PDE4 inhibition','Oral/topical small molecule','PDE4 inhibition','Plaque and/or PsA depending agent','GI/weight/mood or local effects agent-specific','Medical treatment','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-010','TYK2 inhibition','Oral small molecule','Selective TYK2 signaling inhibition','Moderate-severe plaque psoriasis','Agent-specific infection/lab risks','Medical treatment','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-011','TNF inhibition','Biologic','Blocks TNF-alpha','Plaque psoriasis/PsA','Serious infection and class-specific risks','Medical screening/monitoring','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-012','IL-12/23 inhibition','Biologic','Blocks p40 shared subunit','Plaque psoriasis/PsA','Infection and agent-specific risks','Medical screening/monitoring','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-013','IL-17 pathway inhibition','Biologic','Blocks IL-17A, IL-17A/F, or receptor','Plaque psoriasis/PsA','Infection/candidiasis; IBD considerations vary by agent','Medical screening/monitoring','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-014','IL-23 inhibition','Biologic','Blocks IL-23 p19','Plaque psoriasis/PsA for selected agents','Infection and agent-specific risks','Medical screening/monitoring','https://www.aad.org/member/clinical-quality/guidelines/psoriasis'),
('TXC-015','IL-36 receptor inhibition','Biologic','Blocks IL-36 receptor','Generalized pustular psoriasis','Infection/hypersensitivity and agent-specific risks','GPP-specific therapy','https://www.aad.org/member/clinical-quality/guidelines/psoriasis')
